.ds-card { font-family: system-ui, sans-serif; max-width: 380px; padding: 20px; border-radius: 12px; border: 1px solid #cbd5e1; background: #ffffff; color: #0f172a; }
.status-pill { display: inline-block; padding: 3px 10px; border-radius: 6px; background: #dcfce7; color: #166534; font-size: 11px; font-weight: 700; }
.ds-card h3 { margin: 10px 0 6px; font-size: 17px; font-weight: 700; }
.ds-card p { margin: 0 0 14px; font-size: 13px; line-height: 1.5; color: #334155; }
.primary-btn { padding: 8px 14px; border-radius: 8px; border: 2px solid #0284c7; background: #0284c7; color: #ffffff; font-weight: 600; font-size: 13px; cursor: pointer; }

